1 | // apps/api/src/middleware/auth-guard.ts
2 | import { createMiddleware } from "hono/factory";
3 | import { verifyToken } from "../lib/jwt";
4 | import { db, users } from "@finance/db";
5 | import { eq, and, isNull } from "@finance/db";
6 | import { err } from "../lib/response";
7 | import { logger } from "../lib/logger";
8 | 
9 | type AuthVariables = { userId: string; userEmail: string };
10 | 
11 | const ACCESS_COOKIE = "access_token";
12 | 
13 | function getCookieValue(cookieHeader: string, name: string): string | undefined {
14 |   const match = cookieHeader
15 |     .split(";")
16 |     .map((c) => c.trim())
17 |     .find((c) => c.startsWith(`${name}=`));
18 |   return match?.split("=").slice(1).join("=");
19 | }
20 | 
21 | export const authMiddleware = createMiddleware<{ Variables: AuthVariables }>(
22 |   async (c, next) => {
23 |     // 1. HttpOnly cookie (browser sessions)
24 |     const cookieHeader = c.req.header("cookie") ?? "";
25 |     const fromCookie   = getCookieValue(cookieHeader, ACCESS_COOKIE);
26 | 
27 |     // 2. Authorization: Bearer <token> (mobile / API / programmatic)
28 |     const fromHeader = c.req.header("Authorization")?.replace("Bearer ", "");
29 | 
30 |     const token = fromCookie ?? fromHeader;
31 | 
32 |     if (!token) {
33 |       return err(c, 401, "UNAUTHORIZED", "Vui lòng đăng nhập");
34 |     }
35 | 
36 |     try {
37 |       const payload = await verifyToken(token);
38 |       const userId  = String(payload.userId);
39 | 
40 |       // Verify user still exists and is active
41 |       const [user] = await db
42 |         .select({ id: users.id, email: users.email })
43 |         .from(users)
44 |         .where(and(eq(users.id, userId as any), isNull(users.deletedAt)))
45 |         .limit(1);
46 | 
47 |       if (!user) {
48 |         return err(c, 401, "USER_NOT_FOUND", "Tài khoản không tồn tại");
49 |       }
50 | 
51 |       c.set("userId",    String(user.id));
52 |       c.set("userEmail", user.email ?? "");
53 |       return await next();
54 |     } catch (e: any) {
55 |       logger.warn({
56 |         event: "AUTH_GUARD_FAILED",
57 |         message: e.message,
58 |         path:    c.req.path,
59 |         method:  c.req.method,
60 |       });
61 |       return err(c, 401, "TOKEN_INVALID", "Token không hợp lệ hoặc đã hết hạn");
62 |     }
63 |   }
64 | );
