/**
 * WalletsPage — Quản lý ví / tài khoản
 * - Danh sách tất cả ví
 * - Thêm ví mới (inline modal)
 * - Xóa ví / đặt ví mặc định
 * - Không dùng motion/react — CSS transitions thuần
