'use client';

/**
 * WalletsPage — Quản lý ví / tài khoản
 * - Danh sách tất cả ví
 * - Thêm ví mới (inline modal)
 * - Xóa ví / đặt ví mặc định
 * - Không dùng motion/react — CSS transitions thuần
 */

import { useState, useEffect } from 'react';
import {
  Plus, Star, Trash2, Pencil, Wallet as WalletIcon,
  CreditCard, Banknote, PiggyBank, CheckCircle2, X, RefreshCw,
  Building2, TrendingUp, MoreHorizontal,
} from 'lucide-react';
import { useWallet, WalletType, walletTypeLabel } from '@/app/context/WalletContext';
import { CurrencyInput } from '@/components/ui/currency-input';
import { parseCurrencyInput } from '@/_lib/utils/currency-input';
import { formatCurrency, type Wallet } from '@finance/api-client';
import { toast } from 'sonner';
import { Decimal } from 'decimal.js';

// ─── Colour palette for wallet cards ──────────────────────────────────────────

const PRESET_COLORS = [
  '#4361ee', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6',
  '#e91e63', '#06b6d4', '#f97316', '#84cc16', '#6366f1',
];

const WALLET_TYPE_ICONS: Record<WalletType, React.ElementType> = {
  bank:       Building2,
  cash:       Banknote,
  credit:     CreditCard,
  e_wallet:   WalletIcon,
  investment: TrendingUp,
  other:      MoreHorizontal,
};

const WALLET_EMOJIS = ['🏦', '💳', '💵', '📱', '💰', '🏧', '💎', '🎯', '🌟', '⚡'];

// ─── Add/Edit Modal ───────────────────────────────────────────────────────────

export type NewWalletInput = {
  name: string;
  type: WalletType;
  balance: string;
  icon: string;
  color: string;
  isDefault?: boolean;
  accountNumber?: string;
};

interface WalletFormData {
  name: string;
  type: WalletType;
  balance: string;
  icon: string;
  color: string;
  accountNumber: string;
  isDefault: boolean;
}

const defaultForm: WalletFormData = {
  name: '',
  type: 'bank',
  balance: '',
  icon: '🏦',
  color: '#4361ee',
  accountNumber: '',
  isDefault: false,
};

interface AddWalletModalProps {
  isOpen: boolean;
  editWallet?: Wallet | null;
  onClose: () => void;
  onSave: (data: WalletFormData) => void;
  isMutating: boolean;
}

function AddWalletModal({ isOpen, editWallet, onClose, onSave, isMutating }: AddWalletModalProps) {
  const [form, setForm] = useState<WalletFormData>(
    editWallet
      ? {
          name: editWallet.name,
          type: editWallet.type,
          balance: parseCurrencyInput(editWallet.balance),
          icon: editWallet.icon,
          color: editWallet.color,
          accountNumber: editWallet.accountNumber ?? '',
          isDefault: editWallet.isDefault,
        }
      : defaultForm
  );

  // Guard against double-click: use state (not ref) so render reads are valid.
  const [localSubmitting, setLocalSubmitting] = useState(false);

  // Reset local guard when parent signals mutation completed.
  useEffect(() => {
    if (!isMutating) setLocalSubmitting(false);
  }, [isMutating]);

  if (!isOpen) return null;

  const isSubmitting = localSubmitting || isMutating;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    if (!form.name.trim()) {
      toast.error('Vui lòng nhập tên ví');
      return;
    }
    const balNum = Number(form.balance || '0');
    if (isNaN(balNum) || balNum < 0) {
      toast.error('Số dư không hợp lệ');
      return;
    }
    setLocalSubmitting(true);
    onSave(form);
  };

  const TypeIcon = WALLET_TYPE_ICONS[form.type];

  return (
    <div className="fixed inset-0 z-60 flex items-end sm:items-center justify-center p-4">
      {/* Backdrop — blocked during mutation to prevent accidental close */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={isSubmitting ? undefined : onClose}
      />

      {/* Sheet */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-[480px] max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
          <div className="flex items-center gap-3">
            <div
              className="w-9 h-9 rounded-xl flex items-center justify-center text-xl"
              style={{ backgroundColor: form.color + '20' }}
            >
              {form.icon}
            </div>
            <div>
